['def run(context):', "    holdings = context['holdings_data']", "    stage_data = context['stage_data']", '    add_candidates = []', '    trim_candidates = []', '    risk_flags = []', '    # Analyze based on some criteria', '    for holding in holdings:', "        relevant_stage_data = [s for s in stage_data if s['symbol'] == holding['symbol']]", '        if relevant_stage_data:', '            stage_info = relevant_stage_data[0]', "            if stage_info['stage_score'] > 80:", "                add_candidates.append(holding['symbol'])", "            elif stage_info['stage_score'] < 50:", "                trim_candidates.append(holding['symbol'])", '    return add_candidates, trim_candidates, risk_flags']